+export const OPENAI_CLOSED_QA_PROMPT = JSON.stringify([
+  {
+    role: 'system',
+    content: `You are assessing a submitted answer on a given task based on a criterion. Here is the data:
+[BEGIN DATA]
+***
+[Task]: {{input}}
+***
+[Submission]: {{completion}}
+***
+[Criterion]: {{criteria}}
+***
+[END DATA]
