+    duration?: number; // Seconds
+    thumbnail?: string; // Storage ref URL for thumbnail (Sora)
+    spritesheet?: string; // Storage ref URL for spritesheet (Sora)
+    model?: string; // Model used (e.g., 'sora-2', 'veo-3.1-generate-preview')
