+    {
+      input,
+      criteria: expected,
+      completion: tryParse(output),
+      ...(vars || {}),
+    },
+    providerCallContext,
+  );
+  if (resp.error || !resp.output) {
+    return fail(resp.error || 'No output', resp.tokenUsage);
+  }
+
+  invariant(typeof resp.output === 'string', 'model-graded-closedqa produced malformed response');
+  try {
