+      const result = handleTrajectoryStepCount(params);
+      expect(result).toEqual({
+        pass: true,
+        score: 1,
+        reason:
+          'Matched 1 trajectory step(s) for pattern=reasoning* (expected at least 1). Matches: reasoning:reasoning_plan',
+        assertion: params.assertion,
+      });
+    });
+  });
+});
